<template><span class="inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-semibold" :class="badgeClass" :data-testid="testId"><span v-if="dot" class="h-1.5 w-1.5 rounded-full" :class="dotClass"></span>{{ label }}</span></template>
<script setup>
import { computed } from 'vue'
const props=defineProps({status:{type:String,required:true},customMap:{type:Object,default:()=>({})},testId:{type:String,default:'status-badge'}})
const PATTERNS={PENDENTE:{label:'Pendente',class:'border-amber-200 bg-amber-50 text-amber-800',dot:'bg-amber-500'},CONFIRMADA:{label:'Confirmado',class:'border-blue-200 bg-blue-50 text-blue-800',dot:'bg-blue-500'},CONCLUIDA:{label:'Concluído',class:'border-emerald-200 bg-emerald-50 text-emerald-800',dot:'bg-emerald-500'},CANCELADA:{label:'Cancelado',class:'border-red-200 bg-red-50 text-red-800',dot:'bg-red-500'},ACTIVE:{label:'Ativo',class:'border-emerald-200 bg-emerald-50 text-emerald-800',dot:'bg-emerald-500'},EXPIRED:{label:'Expirado',class:'border-amber-200 bg-amber-50 text-amber-800',dot:'bg-amber-500'},REVOKED:{label:'Revogado',class:'border-red-200 bg-red-50 text-red-800',dot:'bg-red-500'},SUPERSEDED:{label:'Substituído',class:'border-slate-200 bg-slate-50 text-slate-700',dot:'bg-slate-400'},not_started:{label:'Não iniciado',class:'border-slate-200 bg-slate-50 text-slate-700',dot:'bg-slate-400'},in_progress:{label:'Em andamento',class:'border-blue-200 bg-blue-50 text-blue-800',dot:'bg-blue-500'},completed:{label:'Concluído',class:'border-emerald-200 bg-emerald-50 text-emerald-800',dot:'bg-emerald-500'}}
const resolved=computed(()=>props.customMap[props.status]||PATTERNS[props.status]||{label:props.status,class:'border-slate-200 bg-slate-50 text-slate-700',dot:'bg-slate-400'}); const label=computed(()=>resolved.value.label); const badgeClass=computed(()=>resolved.value.class); const dotClass=computed(()=>resolved.value.dot); const dot=computed(()=>!!resolved.value.dot)
</script>
